package config
import ("errors";"os";"strings";"time")
type Config struct { HTTPAddr,MediaGateAddr,CoreServiceToken,SynapseBaseURL,SynapseAdminToken string; DBHost,DBPort,DBName,DBUser,DBPassword,RedisAddr string; RequestTimeout time.Duration }
func Load()(Config,error){c:=Config{HTTPAddr:value("CORE_HTTP_ADDR",":8081"),MediaGateAddr:value("MEDIA_GATE_ADDR",":8082"),CoreServiceToken:strings.TrimSpace(os.Getenv("CORE_SERVICE_TOKEN")),SynapseBaseURL:strings.TrimRight(strings.TrimSpace(os.Getenv("SYNAPSE_BASE_URL")),"/"),SynapseAdminToken:strings.TrimSpace(os.Getenv("SYNAPSE_ADMIN_TOKEN")),DBHost:value("DB_HOST","postgres"),DBPort:value("DB_PORT","5432"),DBName:value("DB_DATABASE","dashboard"),DBUser:value("DB_USERNAME","dashboard"),DBPassword:os.Getenv("DB_PASSWORD"),RedisAddr:value("REDIS_ADDR",value("REDIS_HOST","redis")+":"+value("REDIS_PORT","6379")),RequestTimeout:8*time.Second};if c.CoreServiceToken==""||c.SynapseBaseURL==""||c.SynapseAdminToken==""||c.DBPassword==""{return c,errors.New("CORE_SERVICE_TOKEN, SYNAPSE_BASE_URL, SYNAPSE_ADMIN_TOKEN and DB_PASSWORD are required")};return c,nil}
func value(k,d string)string{if v:=strings.TrimSpace(os.Getenv(k));v!=""{return v};return d}
